n=17; seed=8; g=[[0]*n for _ in range(n)]
for r in range(n):
    left,right=seed-r,seed+r
    for c in range(n):
        if c==left or c==right:
            g[r][c]=2
    lo=max(0,left); hi=min(n-1,right)
    for c in range(lo,hi+1):
        if (c-r-seed)%4==0 and g[r][c]==0:
            g[r][c]=1
print(__import__('json').dumps({'action':'submit','grid':g}))

n=17; center=8; g=[[0]*n for _ in range(n)]
for r in range(n):
    for c in range(n):
        if abs(c-center)==r:
            g[r][c]=2
        elif abs(c-center)<r and (c-r-center)%4==0:
            g[r][c]=1
# verify rectangularity, dimensions, coordinate rule, and output serialized
assert len(g)==n and all(len(row)==n for row in g)
print('shape',len(g),set(map(len,g)))
print(__import__('json').dumps({'action':'submit','grid':g},separators=(',',':')))
